function lvlFactor(l) { return Math.pow(LVL.growth, l - LVL.base); }
/* Общая кривая силы врагов по уровню врага (23 ноября): на 1 уровне ХП и атака ниже, к уровню full плавно выходят на 1.0.
   Одинакова для всех видов врагов, элиты и боссов; не зависит от класса героя, умений и квеста. */
const ENEMY_CURVE = { full: 15, hp: 0.45, atk: 0.40, pow: 2 };
function enemyCurve(level, kind) {
  const c = ENEMY_CURVE, start = c[kind];
  if (!Number.isFinite(level) || level >= c.full) return 1;
  const t = Math.max(0, (level - 1) / (c.full - 1)), s = Math.pow(t, c.pow);
  return start + (1 - start) * s;
}
